import re

def parse_notes(notes):
    result = {
        'items': None,
        'adj_pct': 0.0,
        'fee': 0.0,
        'waive': False
    }
    if not notes or notes.strip() == '':
        return result

    s = str(notes)
    # parse items from items=<int>
    m = re.search(r'items\s*=\s*(-?\d+)', s, re.IGNORECASE)
    if m:
        try:
            result['items'] = int(m.group(1))
        except:
            result['items'] = None
    # parse adj_pct from adj=<signed number>% 
    m = re.search(r'adj\s*=\s*([+-]?\d+(?:\.\d+)?)\s*%', s, re.IGNORECASE)
    if m:
        try:
            result['adj_pct'] = float(m.group(1))
        except:
            result['adj_pct'] = 0.0
    # parse fee from fee=<signed number> (can be float)
    m = re.search(r'fee\s*=\s*([+-]?\d+(?:\.\d+)?)', s, re.IGNORECASE)
    if m:
        try:
            result['fee'] = float(m.group(1))
        except:
            result['fee'] = 0.0
    # waive from waive=true (case-insensitive)
    m = re.search(r'waive\s*=\s*(true|false)', s, re.IGNORECASE)
    if m:
        val = m.group(1).lower()
        result['waive'] = (val == 'true')
    else:
        result['waive'] = False
    return result

