import math

def choose_best(rows_for_rid):
    # rows_for_rid: list of row dicts with same rid
    # choose: latest event_time; if tie in event_time (same datetime), break ties by preferring version with a real net result, then earlier file order
    best = None
    for r in rows_for_rid:
        if best is None:
            best = r
            continue
        # compare
        # latest event_time first
        et_b = best['et']
        et_r = r['et']
        # handle None? event_time might be None
        if et_r != et_b:
            # want latest - so if et_r is later, replace
            if et_r is not None and et_b is None:
                best = r; continue
            if et_r is None and et_b is not None:
                continue  # keep best
            if et_r > et_b:
                best = r; continue
            if et_r < et_b:
                continue
        # tie in event_time
        # prefer version with a real net result (not NaN)
        net_b_real = not math.isnan(best['net'])
        net_r_real = not math.isnan(r['net'])
        if net_r_real != net_b_real:
            if net_r_real and not net_b_real:
                best = r; continue
            if net_b_real and not net_r_real:
                continue
        # earlier file order
        if r['file_order'] < best['file_order']:
            best = r; continue
        if r['file_order'] > best['file_order']:
            continue
    return best
